  ('42493d15-ac15-531b-a412-ae1460e0ef4d', 'Telangana egg pulusu with rice', 'telangana', 'dinner', 'egg', 2, 30, '["Boil and peel the eggs; fry them lightly in a little oil.","Cook onion and tomato with the powders.","Add tamarind water and jaggery; simmer 10 min.","Add the eggs and simmer 5 min. Serve with rice."]'::jsonb, 'Eggs soak up the tangy pulusu beautifully.', 'Tangy, spicy and protein-rich.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 533, 21.4, 20.3, 66.6, 0.997, false, '{"curry leaves"}', '2026-01-01T00:00:00Z'),
  ('1692a93d-16b3-5104-aa20-7c544f75db4d', 'Garlic pepper tuna with sautéed greens', 'mixed', 'dinner', 'nonveg', 2, 20, '["Season tuna steaks with pepper, salt and lemon.","Sear in hot oil 2–3 min per side.","Sauté garlic and greens in the same pan till wilted."]'::jsonb, 'About 40 g protein in a 20-minute dinner.', 'Clean, fast and high-protein.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 294, 47.4, 7.5, 9.3, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('c3a9b9a9-8016-5b4c-a95e-a7f560589da0', 'Paneer Chettinad with jeera rice', 'tamil', 'lunch', 'veg', 2, 35, '["Dry-roast coconut, pepper and fennel; grind to a paste.","Cook onion, ginger-garlic and tomato in oil with the powders.","Add the paste and a cup of water; simmer 5 min.","Add paneer cubes and peas; simmer 5 min.","Cook rice with cumin."]'::jsonb, 'Swap a third of the rice for extra peas to raise protein.', 'Chettinad spice, vegetarian protein.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 759, 28.8, 31.6, 90.7, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('24bbd899-a19c-514c-a86b-7d68e11912c7', 'Sprouts and paneer kosambari bowl with foxtail millet', 'karnataka', 'lunch', 'veg', 2, 20, '["Cook the millet (1:2.5 water) and cool slightly.","Steam the sprouts 4 min.","Toss sprouts, grated carrot, cucumber, cubed paneer and coconut with lemon and salt.","Temper mustard and green chilli in oil and pour over. Serve on the millet."]'::jsonb, 'Raw-crunchy sprouts keep more of their vitamin C.', 'A fresh, no-fuss protein bowl.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 549, 22, 21.8, 68.3, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('889747d7-20ae-5171-af03-14e948d6322f', 'Meal maker (soya chunk) pepper fry with chapati', 'tamil', 'lunch', 'veg', 2, 30, '["Boil soya chunks 5 min, rinse and squeeze dry.","Make 4 chapatis.","Fry onion, ginger-garlic and capsicum in oil; add tomato and turmeric.","Add the chunks and roast with crushed pepper and fennel till dry."]'::jsonb, 'Soya chunks are one of the cheapest vegetarian protein sources.', 'Meaty texture, all plant protein.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 496, 33.5, 9.4, 74.8, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('9ab3bab6-126f-5bf1-a442-82a2888b1320', 'Kerala kadala curry with ragi puttu', 'kerala', 'lunch', 'veg', 2, 45, '["Soak black chana overnight and pressure-cook.","Roast half the coconut till brown and grind with the powders.","Cook shallots, ginger-garlic and tomato in coconut oil; add chana, the paste and water; simmer 10 min.","For puttu: rub ragi flour with salt and a little water, layer with the rest of the coconut and steam 8 min."]'::jsonb, 'Add a bowl of yogurt to round out the protein.', 'Kerala breakfast classic, made a protein lunch.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 664, 22.6, 21.8, 100.6, 1, false, '{}', '2026-01-01T00:00:00Z'),
