  ('59eba585-1c7b-51fd-a473-a7c1c77e1b2e', 'Protein bisibele bath with millet and peanuts', 'karnataka', 'lunch', 'veg', 2, 45, '["Pressure-cook dal and millet together with vegetables and turmeric.","Add tamarind water and sambar powder; simmer to a soft porridge.","Temper mustard, curry leaves and peanuts in ghee and pour over.","Serve with yogurt."]'::jsonb, 'Millet in place of rice adds fibre without losing the comfort.', 'Karnataka one-pot, upgraded.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 615, 26.2, 17.9, 92.1, 0.997, false, '{"curry leaves"}', '2026-01-01T00:00:00Z'),
  ('bef17855-8032-567b-aa5e-93f73e5c236e', 'Paneer and sprouts dum biryani', 'mixed', 'lunch', 'veg', 2, 50, '["Marinate paneer and sprouts in yogurt, ginger-garlic, garam masala and salt.","Par-boil the rice.","Brown the onion in ghee.","Layer marinade, onion, mint and rice; cover tightly and cook on low 20 min."]'::jsonb, 'Sprouts add bite and extra protein to a classic biryani.', 'Festive flavour, protein-forward.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 703, 26.3, 24.4, 93.8, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('4356d654-6db2-5a7a-ae74-1d612e3b1968', 'Tuna varutharacha curry with red rice', 'kerala', 'lunch', 'nonveg', 2, 40, '["Roast coconut, shallots, coriander and fennel till dark brown; grind with chilli.","Cook tomato in coconut oil; add the paste, tamarind water and salt.","Simmer 8 min, add tuna and cook 6 min."]'::jsonb, 'Roasted-coconut gravy means a little goes a long way.', 'Deep Kerala flavour around lean tuna.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 626, 50.6, 18.2, 66.8, 0.997, false, '{"curry leaves"}', '2026-01-01T00:00:00Z'),
