  ('a51dad8b-9ff8-571f-ab65-838be99913cd', 'Keema-stuffed capsicum', 'mixed', 'dinner', 'nonveg', 2, 35, '["Cook onion, ginger-garlic and tomato; add mince and spices; cook dry.","Halve and seed the capsicums; fill with keema.","Top with a little grated cheese and bake at 200 °C for 15 min."]'::jsonb, 'Capsicum boats replace bread or rice.', 'Low-carb, high-protein and pretty on the plate.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 350, 27.9, 20.9, 15.1, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('616e568e-4575-5c8b-afbc-973bff1b1b04', 'Quinoa moong pongal with ghee and curd', 'tamil', 'dinner', 'veg', 2, 30, '["Roast moong dal lightly; pressure-cook with quinoa and 4 cups water till soft.","Mash and season with salt.","Temper pepper, cumin, ginger, cashew and curry leaves in ghee and pour over.","Serve with curd."]'::jsonb, 'Quinoa in place of rice keeps the comfort and adds protein.', 'Temple-style pongal, reinvented.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 461, 20.6, 14.5, 64.3, 0.995, false, '{"curry leaves"}', '2026-01-01T00:00:00Z'),
  ('41a419a9-2d7f-5d46-a51f-e73d3200b5e2', 'Black chana and spinach curry with chapati', 'mixed', 'dinner', 'veg', 2, 35, '["Pressure-cook soaked black chana.","Cook onion, ginger-garlic and tomato with spices.","Add spinach and chana with a little water; simmer 8 min.","Serve with chapatis and yogurt."]'::jsonb, 'Iron from spinach and chana absorbs better with the tomato''s vitamin C.', 'Earthy, iron- and protein-rich.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 535, 23.3, 12.9, 89.4, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('5607861e-a5b3-56bb-adb3-067f83e12aba', 'Egg and sprouts bhurji wrap', 'mixed', 'dinner', 'egg', 2, 20, '["Make 2 large chapatis.","Sauté onion, chilli and tomato; add sprouts and cook 3 min.","Scramble in the eggs with turmeric and salt.","Roll in the chapatis with lettuce."]'::jsonb, 'Sprouts make the bhurji go further for more protein per bite.', 'Dinner you can eat on the go.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 434, 23.5, 17.7, 49.2, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('9dbbfd90-3a57-5e18-a310-4de5f17a7ee8', 'Tilapia moilee with steamed vegetables', 'kerala', 'dinner', 'nonveg', 2, 30, '["Sauté onion, ginger, garlic, chilli and curry leaves in coconut oil without browning.","Add turmeric and coconut milk; bring to a simmer.","Add fish and cook gently 6–8 min.","Steam the vegetables to serve alongside."]'::jsonb, 'Mild, creamy and gentle on the stomach at night.', 'Kerala''s mildest curry.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 447, 39.2, 26.1, 19, 0.998, false, '{"curry leaves"}', '2026-01-01T00:00:00Z'),
  ('00fd3110-2ff7-50c5-a6a7-ba9a4c7dd5a1', 'Baked soya-paneer cutlets with mint chutney', 'mixed', 'dinner', 'veg', 2, 35, '["Boil and squeeze soya chunks; mince them.","Mash with paneer, boiled potato, onion, chilli, ginger, garam masala, besan and salt.","Shape into patties, brush with oil and bake at 200 °C for 20 min, turning once.","Blend mint, coriander, yogurt and lemon for the chutney."]'::jsonb, 'Baking instead of deep-frying saves a lot of oil.', 'Party-snack flavour as a proper dinner.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 509, 33.2, 20.3, 48.5, 1, false, '{}', '2026-01-01T00:00:00Z'),
  ('22b968cb-4578-5584-aec8-bbc0ee3c34f5', 'Chicken milagu rasam soup with boiled eggs', 'tamil', 'dinner', 'nonveg', 2, 35, '["Simmer chicken with tomato, ginger and a litre of water for 20 min.","Crush pepper, cumin and garlic; temper in ghee with curry leaves and add to the pot with tamarind.","Simmer 5 min. Serve hot with a boiled egg each."]'::jsonb, 'A soothing, high-protein dinner when you''re feeling under the weather.', 'Grandma''s pepper rasam, with chicken.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 340, 41.3, 14.9, 9, 0.997, false, '{"curry leaves"}', '2026-01-01T00:00:00Z'),
  ('1d6bf140-5f01-5e0d-a817-9b441a29050c', 'Thayir (curd) chicken with salad', 'tamil', 'dinner', 'nonveg', 2, 35, '["Marinate chicken in half the hung curd with ginger-garlic, turmeric and salt for 20 min.","Cook onion and chilli in oil; add the chicken and cook 12 min.","Lower the heat and stir in the rest of the curd with coriander powder; simmer gently 3 min.","Serve with salad."]'::jsonb, 'Hung curd gives a creamy gravy with extra protein instead of cream.', 'Creamy, tangy and very high in protein.', 'built-in library (written by Claude)', 'library-2026-11-18', null, 'computed', 355, 49.1, 10.6, 14.9, 1, false, '{}', '2026-01-01T00:00:00Z')
